function topoSort(graph) {
 const tasks = new Set();
 const adj = new Map(); // task -> list of tasks that depend on it (i.e., tasks that come after)
 const inDegree = new Map(); // task -> number of unresolved dependencies

 // Initialize tasks and in-degrees
 for (const task of Object.keys(graph)) {
 tasks.add(task);
 if (!adj.has(task)) adj.set(task, []);
 if (!inDegree.has(task)) inDegree.set(task, 0);
 }

 // Process dependencies
 for (const task of Object.keys(graph)) {
 const deps = graph[task];
 if (!Array.isArray(deps)) continue;
 for (const dep of deps) {
 tasks.add(dep);
 if (!adj.has(dep)) adj.set(dep, []);
 if (!inDegree.has(dep)) inDegree.set(dep, 0);
 // dep must come before task, so task depends on dep
 inDegree.set(task, (inDegree.get(task) || 0) + 1);
 }
 }

 // Ensure all tasks have an entry in adj and inDegree
 for (const task of tasks) {
 if (!adj.has(task)) adj.set(task, []);
 if (!inDegree.has(task)) inDegree.set(task, 0);
 }

 const result = [];
 const remaining = new Set(tasks);

 while (remaining.size > 0) {
 // Find the smallest task with in-degree 0
 let minTask = null;
 for (const task of remaining) {
 if (inDegree.get(task) === 0 && minTask === null || task < minTask) {
 minTask = task;
 }
 }

 if (minTask === null) {
 // No task with in-degree 0 but remaining tasks exist -> cycle
 throw new Error('cycle');
 }

 remaining.delete(minTask);
 result.push(minTask);

 // Reduce in-degrees of tasks that depend on minTask
 for (const dependent of adj.get(minTask) || []) {
 if (remaining.has(dependent)) {
 inDegree.set(dependent, inDegree.get(dependent) - 1);
 }
 }
 }

 return result;
}

