function formatBytes(n) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError('n must be a finite number');
  }
  if (!Number.isInteger(n) || n < 0) {
    throw new RangeError('n must be a non-negative integer');
  }

  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = n;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex++;
  }

  // Round to at most one decimal place
  const rounded = Math.round(value * 10) / 10;

  // If rounding made it exactly 1024 and there's a larger unit, move up
  if (rounded === 1024 && unitIndex < units.length - 1) {
    value = 1;
    unitIndex++;
  }

  // Format the number: remove trailing .0
  const formattedValue = rounded % 1 === 0 ? rounded.toString() : rounded.toFixed(1);
  return `${formattedValue} ${units[unitIndex]}`;
}

module.exports = { formatBytes };
