        raise ValueError(f"Invalid version string: {a}")

    try:
        b_parsed = parse_version(b)
    except ValueError:
        raise ValueError(f"Invalid version string: {b}")

    # Compare major, minor, patch
    if a_parsed[0] < b_parsed[0]:
        return -1
    elif a_parsed[0] > b_parsed[0]:
        return 1

    if a_parsed[1] < b_parsed[1]:
        return -1
    elif a_parsed[1] > b_parsed[1]:
        return 1

    if a_parsed[2] < b_parsed[2]:
        return -1
    elif a_parsed[2] > b_parsed[2]:
        return 1

    # Compare prerelease
    prerelease_a = a_parsed[3]
    prerelease_b = b_parsed[4]

    if prerelease_a is None and prerelease_b is None:
