        # If all shared parts are equal, the one with more parts has higher precedence
        if i == len(parts_a) - 1 and len(parts_a) < len(parts_b):
            return -1
        if i == len(parts_b) - 1 and len(parts_b) < len(parts_a):
            return 1

    # If all parts are equal, they are equal
    return 0
