        raise TypeError("Input must be a string")
    if not s:
        return ""
    result = []
    i = 0
    while i < len(s):
        # Parse count
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("Missing count")
        count_str = s[i:j]
        count = int(count_str)
        if count == 0:
            raise ValueError("Count must be at least 1")
        if j >= len(s):
            raise ValueError("Trailing digits with no character")
        char = s[j]
        if char.isdigit():
            raise ValueError("Character must be non-digit")
        result.append(char * count)
        i = j + 1
    return "".join(result)
